import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';

const AttendancePage = () => {
  const [allEmployees, setAllEmployees] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [activeFilter, setActiveFilter] = useState('All');
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [showCalendar, setShowCalendar] = useState(false);
  const [attendanceRecords, setAttendanceRecords] = useState({});

  // 1. Fetch ALL employees from backend
  useEffect(() => {
    const fetchAllEmployees = async () => {
      setIsLoading(true);
      try {
        const response = await axios.get('http://127.0.0.1:8000/api/employees/');
        let employeesData = [];
        if (response.data && Array.isArray(response.data.results)) {
          employeesData = response.data.results;
        } else if (Array.isArray(response.data)) {
          employeesData = response.data;
        }
        setAllEmployees(employeesData);
      } catch (error) {
        console.error("Error fetching employees:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchAllEmployees();
  }, []);

  // 2. Simulate today's attendance
  const attendanceData = allEmployees.map((employee, index) => {
    const statuses = ['Present', 'Absent', 'On Leave'];
    return {
      ...employee,
      status: statuses[index % statuses.length],
    };
  });

  // 3. Filter data
  const filteredAttendance = attendanceData.filter((staff) => {
    if (activeFilter === 'All') return true;
    return staff.status === activeFilter;
  });

  // 4. Generate random attendance for the month
  const generateMonthlyAttendance = () => {
    const today = new Date();
    const year = today.getFullYear();
    const month = today.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const records = {};
    const statuses = ['Present', 'Absent', 'Half Day'];
    for (let day = 1; day <= daysInMonth; day++) {
      const date = new Date(year, month, day);
      records[date.toDateString()] =
        statuses[Math.floor(Math.random() * statuses.length)];
    }
    return records;
  };

  // 5. Handle calendar view
  const handleViewAttendance = (employee) => {
    setSelectedEmployee(employee);
    setAttendanceRecords(generateMonthlyAttendance());
    setShowCalendar(true);
  };

  const getStatusBadgeClass = (status) => {
    switch (status) {
      case 'Present':
        return 'bg-green-100 text-green-800';
      case 'Absent':
        return 'bg-red-100 text-red-800';
      case 'On Leave':
        return 'bg-yellow-100 text-yellow-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  const getFilterButtonClass = (filter) => {
    return activeFilter === filter
      ? 'bg-blue-600 text-white'
      : 'bg-gray-200 text-gray-700 hover:bg-gray-300';
  };

  return (
    <div className="p-8">
      <div className="mb-6">
        <h1 className="text-3xl font-bold text-gray-800">Today's Attendance</h1>
        <p className="text-sm text-gray-500">
          A summary of staff and faculty attendance for today.
        </p>
      </div>

      {/* Filter Buttons */}
      <div className="mb-6 flex space-x-2">
        {['All', 'Present', 'Absent', 'On Leave'].map((filter) => (
          <button
            key={filter}
            onClick={() => setActiveFilter(filter)}
            className={`px-4 py-2 rounded-lg text-sm font-medium ${getFilterButtonClass(
              filter
            )}`}
          >
            {filter}
            {filter === 'All' && ` (${attendanceData.length})`}
          </button>
        ))}
      </div>

      {/* Attendance Table */}
      <div className="bg-white p-6 rounded-lg shadow-md">
        {isLoading ? (
          <div className="text-center py-8 text-gray-500">
            Loading employee data...
          </div>
        ) : (
          <table className="w-full text-sm text-left">
            <thead className="text-xs uppercase bg-gray-100 text-gray-600">
              <tr>
                <th className="px-6 py-3">Staff Name</th>
                <th className="px-6 py-3">Department</th>
                <th className="px-6 py-3">Status</th>
                <th className="px-6 py-3 text-center">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredAttendance.map((staff) => (
                <tr
                  key={staff.id}
                  className="border-b hover:bg-gray-50 transition"
                >
                  <td className="px-6 py-4 font-medium text-gray-800">
                    {staff.firstName} {staff.lastName}
                  </td>
                  <td className="px-6 py-4 text-gray-700">
                    {staff.department}
                  </td>
                  <td className="px-6 py-4">
                    <span
                      className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusBadgeClass(
                        staff.status
                      )}`}
                    >
                      {staff.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <button
                      onClick={() => handleViewAttendance(staff)}
                      className="px-3 py-1 bg-blue-500 text-white rounded-md hover:bg-blue-600 text-xs"
                    >
                      View Attendance
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* Calendar Modal */}
      {showCalendar && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-lg w-[420px] shadow-lg relative">
            <h2 className="text-xl font-semibold mb-2 text-gray-800">
              {selectedEmployee?.firstName} {selectedEmployee?.lastName} — Attendance
            </h2>

            <Calendar
              className="rounded-md"
              tileContent={({ date }) => {
                const status = attendanceRecords[date.toDateString()];
                if (status === 'Present')
                  return (
                    <div className="bg-green-400 w-2 h-2 rounded-full mx-auto mt-1"></div>
                  );
                if (status === 'Absent')
                  return (
                    <div className="bg-red-400 w-2 h-2 rounded-full mx-auto mt-1"></div>
                  );
                if (status === 'Half Day')
                  return (
                    <div className="bg-yellow-400 w-2 h-2 rounded-full mx-auto mt-1"></div>
                  );
              }}
            />

            <div className="flex justify-between mt-4 text-sm text-gray-600">
              <div className="flex items-center space-x-1">
                <span className="bg-green-400 w-3 h-3 rounded-full"></span>
                <span>Present</span>
              </div>
              <div className="flex items-center space-x-1">
                <span className="bg-red-400 w-3 h-3 rounded-full"></span>
                <span>Absent</span>
              </div>
              <div className="flex items-center space-x-1">
                <span className="bg-yellow-400 w-3 h-3 rounded-full"></span>
                <span>Half Day</span>
              </div>
            </div>

            <button
              onClick={() => setShowCalendar(false)}
              className="absolute top-2 right-3 text-gray-500 hover:text-gray-800 text-xl font-bold"
            >
              ×
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AttendancePage;
